using System;
using System.Collections.Generic;
using System.Data;
using System.Data.Common;
using System.Linq;

namespace pengdows.AdoNetApiTest.conformance;

/// <summary>
/// Type fidelity over every type the connected database advertises in <c>GetSchema("DataTypes")</c>, with the catalog
/// generated by <see cref="DataTypesCatalog"/>. It needs no catalog from the provider: a derived class with the
/// provider's fixture is enough, and <see cref="IDataTypesFidelityFixture"/> only where the SQL-92 defaults do not work.
/// A provider without the collection reports the tests as not implemented.
/// </summary>
public abstract partial class DataTypesFidelityTestBase<TFixture> : FidelityTestBase<TFixture>
	where TFixture : class, IDbFactoryFixture
{
	private GeneratedCatalog _catalog;
	private string _unavailable;
	private string _marker;

	protected DataTypesFidelityTestBase(TFixture fixture)
		: base(fixture)
	{
	}

	/// <summary>The generated catalog, or <c>null</c> when the provider has no usable <c>DataTypes</c> collection.</summary>
	protected GeneratedCatalog Catalog
	{
		get
		{
			if (_catalog is null && _unavailable is null)
			{
				Load();
			}

			return _catalog;
		}
	}

	protected override IReadOnlyList<TypeSpec> Specs => Catalog?.Types ?? Array.Empty<TypeSpec>();

	protected override string CreateTableSql(string table, string columnSql) => Fixture is IDataTypesFidelityFixture fixture
		? fixture.CreateTableSql(table, columnSql)
		: $"create table {table} (Id integer not null primary key, V {columnSql})";

	protected override string DropTableSql(string table) => Fixture is IDataTypesFidelityFixture fixture
		? fixture.DropTableSql(table)
		: $"drop table {table}";

	protected override string ParameterMarker(string name)
	{
		if (_marker is null)
		{
			using var connection = CreateOpenConnection();
			_marker = MakeParameterName(connection, "p");
		}

		return name == "p" ? _marker : _marker.Substring(0, _marker.Length - 1) + name;
	}

	/// <summary>Runs <paramref name="paths"/> over the generated catalog, or reports why there is none.</summary>
	protected void RunGenerated(Paths paths, bool reportUncovered)
	{
		if (Catalog is null)
		{
			ConformanceOutcome.NotImplemented(_unavailable);
			return;
		}

		if (reportUncovered)
		{
			foreach (var uncovered in Catalog.Uncovered)
			{
				ConformanceOutcome.Finding(uncovered.Name + DataTypesCatalog.Label, "(advertised)", "metadata", FidelityStatus.NotApplicable, "not covered: " + uncovered.Reason);
			}
		}

		Run(paths);
	}

	private void Load()
	{
		DataTable dataTypes;
		using (var connection = CreateOpenConnection())
		{
			try
			{
				dataTypes = connection.GetSchema(DbMetaDataCollectionNames.DataTypes);
			}
			catch (Exception ex) when (ex is NotSupportedException or NotImplementedException or ArgumentException or InvalidOperationException)
			{
				_unavailable = $"The provider has no DataTypes collection ({ex.GetType().Name}: {ex.Message}).";
				return;
			}
		}

		if (dataTypes.Rows.Count == 0)
		{
			_unavailable = "The provider's DataTypes collection is empty.";
			return;
		}

		var render = Fixture is IDataTypesFidelityFixture fixture ? fixture.RenderAsText : "CAST({0} AS VARCHAR(4000))";
		_catalog = DataTypesCatalog.Build(dataTypes, ResolveType);
		foreach (var spec in _catalog.Types)
		{
			spec.RenderAsText = render;
		}
	}

	/// <summary>A <c>DataType</c> name, looked up in the provider's assembly before the framework's.</summary>
	private Type ResolveType(string name)
	{
		return Fixture.Factory.GetType().Assembly.GetType(name, throwOnError: false)
			?? Type.GetType(name, throwOnError: false)
			?? AppDomain.CurrentDomain.GetAssemblies().Select(assembly => assembly.GetType(name, throwOnError: false)).FirstOrDefault(type => type is not null);
	}
}
